package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.TimeUnit;
/** Synthetic Android checks for the interactive chart, exact selection and bounded detail sheet. */
final class ChartUpgradeChecks {
 static int checks;static void yes(boolean value,String text)throws Exception{checks++;if(!value)throw new Exception(text);}
 static void main(Instrumentation test,VisualChecks.Step work)throws Exception{VisualChecks.main(test,work);}
 static void ready(Instrumentation test,SheetDialog dialog)throws Exception{long until=SystemClock.uptimeMillis()+10000;while(dialog.layout.findViewWithTag("spending-chart")==null&&SystemClock.uptimeMillis()<until)V15Checks.pause(test,60);yes(dialog.layout.findViewWithTag("spending-chart")!=null,"chart detail finishes its background projection");V15Checks.pause(test,220);}
 static int run(Instrumentation test,Context c)throws Exception {
  checks=0;NativeSync.EXEC.submit(()->{}).get(15,TimeUnit.SECONDS);Map<String,Object> secure=VisualChecks.preferences(c.getSharedPreferences("secure",0)),settings=VisualChecks.preferences(NativeStore.settings(c)),updates=VisualChecks.preferences(AppUpdates.prefs(c));MainActivity[] host={null};SheetDialog[] detail={null};
  try{
   JSONObject data=VisualChecks.fixture();JSONArray transactions=new JSONArray();for(int i=0;i<3;i++)transactions.put(NativeSync.transaction("expense",new long[]{30000,21200,9990}[i],"bank-mach","",new String[]{"expense-0","expense-1","expense-7"}[i],new String[]{"Alimentación sintética","Transporte sintético","Netflix"}[i],"manual","").put("id","chart-upgrade-"+i));data.put("transactions",transactions);LocalData.restore(c,data);NativeStore.settings(c).edit().putBoolean("detectionTutorialSeen",true).putBoolean("capture",false).putBoolean("privateScreen",false).putBoolean("alertChanges",false).putBoolean("alertDetections",false).putBoolean("alertVerifications",false).putString("appearance","dark").commit();AppUpdates.prefs(c).edit().putLong("attempt",System.currentTimeMillis()).commit();
   host[0]=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity a=host[0];V16Checks.loaded(test,a);String before=LocalData.read(c).toString();
   DonutChart[] standalone={null};main(test,()->{
    standalone[0]=new DonutChart(a,new long[]{30000,21200,9990},SpendingDetail.COLORS);DonutChart chart=standalone[0];chart.setLabels(new String[]{"Alimentación","Transporte","Suscripciones"});chart.layout(0,0,a.dp(260),a.dp(260));float total=0;for(int i=0;i<chart.sweeps.length;i++){total+=chart.sweeps[i];yes(Math.abs(chart.sweeps[i]-360d*chart.values[i]/61190)<.001,"visual finish never distorts a category angle");double mid=Math.toRadians(chart.starts[i]+chart.sweeps[i]/2);yes(chart.hit(chart.cx+(float)Math.cos(mid)*chart.r,chart.cy+(float)Math.sin(mid)*chart.r)==i,"sector hit test reaches its true category");}yes(Math.abs(total-360)<.001,"segments still make one exact circle");yes(chart.hit(chart.cx,chart.cy)==-1,"centre is not mistaken for a category");yes(chart.hit(0,0)==-1,"outside touches do not choose spending");
    Object firstMaterial=chart.materials[0];chart.select(1,false);yes(chart.selected==1,"programmatic legend selection uses one sector");chart.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null);yes(chart.selected==2,"TalkBack forward chooses the next actual sector");chart.onKeyDown(KeyEvent.KEYCODE_DPAD_LEFT,new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_LEFT));yes(chart.selected==1,"keyboard navigation matches the chart order");Bitmap image=Bitmap.createBitmap(a.dp(260),a.dp(260),Bitmap.Config.ARGB_8888);chart.draw(new Canvas(image));yes(chart.materials[0]==firstMaterial,"selection and redraw reuse cached segment shaders");int nonzero=0;for(int y=0;y<image.getHeight();y+=8)for(int x=0;x<image.getWidth();x+=8)if(Color.alpha(image.getPixel(x,y))>0)nonzero++;yes(nonzero>50,"cached sector paths really render on Android");image.recycle();
    int old=chart.selected;double angle=Math.toRadians(chart.starts[0]+chart.sweeps[0]/2);float x=chart.cx+(float)Math.cos(angle)*chart.r,y=chart.cy+(float)Math.sin(angle)*chart.r;long at=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(at,at,MotionEvent.ACTION_DOWN,x,y,0),move=MotionEvent.obtain(at,at+50,MotionEvent.ACTION_MOVE,x,y+a.dp(80),0),up=MotionEvent.obtain(at,at+90,MotionEvent.ACTION_UP,x,y+a.dp(80),0);chart.onTouchEvent(down);chart.onTouchEvent(move);chart.onTouchEvent(up);down.recycle();move.recycle();up.recycle();yes(chart.selected==old,"scrolling over a chart cannot accidentally change its category");
    DonutChart zero=new DonutChart(a,new long[]{0,0},SpendingDetail.COLORS);zero.layout(0,0,a.dp(180),a.dp(180));yes(zero.total==0&&zero.sweeps[0]==0&&!zero.isClickable(),"empty chart has no invented sectors or clickable fake data");
   });
   main(test,()->detail[0]=SpendingDetail.show(a,0,Ledger.today().substring(0,7),-1));ready(test,detail[0]);DonutChart chart=detail[0].layout.findViewWithTag("spending-chart");yes(chart.total==61190&&chart.values.length==3,"detail uses exact same synthetic total and category count");
   main(test,()->detail[0].layout.findViewWithTag("spending-category:1").performClick());V15Checks.pause(test,180);yes(chart.selected==1,"tapping a legend really selects its sector");TextView selected=detail[0].layout.findViewWithTag("spending-selection");yes(selected.getText().toString().contains("35%"),"selected category shows its proper share");LinearLayout rows=detail[0].layout.findViewWithTag("spending-records");List<View> choices=VisualChecks.views(rows,View.class);int transport=0,unrelated=0;for(View view:choices){String text=view.getContentDescription()==null?"":view.getContentDescription().toString();if(text.startsWith("Transporte sintético."))transport++;if(text.startsWith("Alimentación sintética.")||text.startsWith("Netflix."))unrelated++;}yes(transport==1&&unrelated==0,"selection opens only its ID-matched movements");UiSmoke.shot(test,c,"phase4-spending-selected");
   main(test,()->selected.performClick());V15Checks.pause(test,100);yes(chart.selected==-1,"selected filter has an explicit reset to all categories");
   main(test,()->detail[0].layout.findViewWithTag("spending-mode:2").performClick());ready(test,detail[0]);DonutChart accounts=detail[0].layout.findViewWithTag("spending-chart");yes(accounts.total==61190&&accounts.values.length==1,"account mode shows the same money grouped by account");main(test,()->detail[0].dismiss());
   String previous=java.time.LocalDate.parse(Ledger.today()).withDayOfMonth(1).minusMonths(1).toString().substring(0,7);main(test,()->detail[0]=SpendingDetail.show(a,0,previous,-1));ready(test,detail[0]);DonutChart historical=detail[0].layout.findViewWithTag("spending-chart");yes(historical.total==0,"historical detail cannot fall back to current-month records");main(test,()->detail[0].dismiss());yes(before.equals(LocalData.read(c).toString()),"chart gestures, selected detail, account view and historical periods never write financial data");
  }finally{
   if(detail[0]!=null)main(test,()->detail[0].dismiss());if(host[0]!=null)main(test,()->host[0].finish());test.waitForIdleSync();NativeSync.EXEC.submit(()->{}).get(15,TimeUnit.SECONDS);VisualChecks.restore(c.getSharedPreferences("secure",0),secure);VisualChecks.restore(NativeStore.settings(c),settings);VisualChecks.restore(AppUpdates.prefs(c),updates);
  }
  return checks;
 }
}
